func (r *IncidentsOutgoingEmailIntegrationResource) ModifyPlan(ctx context.Context, req resource.ModifyPlanRequest, resp *resource.ModifyPlanResponse) {
	refuseUnnamedTeam(ctx, req, resp, r.client, "incidents outgoing email integration")
	warnKeptOnRemoval(ctx, "betterstack_incidents_outgoing_email_integration", req, resp, incidentsOutgoingEmailIntegrationKeptOnRemoval)
}

func (r *IncidentsOutgoingEmailIntegrationResource) ImportState(ctx context.Context, req resource.ImportStateRequest, resp *resource.ImportStateResponse) {
	markImported(ctx, resp.Private, &resp.Diagnostics)
	resource.ImportStatePassthroughID(ctx, path.Root("id"), req, resp)
	resp.Diagnostics.Append(resp.State.SetAttribute(ctx, path.Root("on_incident_started"), true)...)
	resp.Diagnostics.Append(resp.State.SetAttribute(ctx, path.Root("on_incident_acknowledged"), true)...)
	resp.Diagnostics.Append(resp.State.SetAttribute(ctx, path.Root("on_incident_resolved"), true)...)
	resp.Diagnostics.Append(resp.State.SetAttribute(ctx, path.Root("on_incident_reopened"), true)...)
	resp.Diagnostics.Append(resp.State.SetAttribute(ctx, path.Root("on_incident_comment"), true)...)
	resp.Diagnostics.Append(resp.State.SetAttribute(ctx, path.Root("notify_alongside_primary_responder"), true)...)
}
